  1	/**
  2	 * GitHub repo-membership ACL SYNC — the production path that populates the repo
  3	 * graph the resource gate reads, mirroring `./slack-acl-sync` for the second
  4	 * source. Per GitHub connection: enumerate the repos it captures (from its
  5	 * feeds), fetch each repo's collaborators, and hand them to `buildGithubRepoGraph`
  6	 * (which materializes the `member_of` edges, reconciles departures, and stamps
  7	 * the connection `full`/`fresh`).
  8	 *
  9	 * Fail-closed on error, ATOMIC per connection: if ANY repo's collaborator fetch
 10	 * throws (GitHub outage, token expiry, repo gone), we mark the connection's ACL
 11	 * state `failed` rather than build a half-synced graph — but only DOWNGRADE an
 12	 * existing row (a connection that has never been graphed stays on the legacy
 13	 * fence). The external calls (repo list, collaborator fetch) are injected so the
 14	 * sync logic is tested with stubs and the live tick wires the real GitHub API.
 15	 */
 16	
 17	import { createLogger } from '@lobu/core';
 18	import { getDb } from '../db/client.js';
 19	import { getInstallationTokenRegistry } from '../gateway/installation/registry.js';
 20	import type { CoreServices } from '../gateway/services/core-services.js';
 21	import type { AppInstallationStore } from '../lobu/stores/app-installation-store.js';
 22	import {
 23	  type GithubRepoCollaborator,
 24	  githubAclSource,
 25	  githubReposToResources,
 26	} from '@lobu/connectors/github-identity';
 27	import {
 28	  clearConnectionAclError,
 29	  markConnectionAclFailed,
 30	} from './acl-observability.js';
 31	import { buildAccessGraph } from './access-graph.js';
 32	
 33	const logger = createLogger('github-acl-sync');
 34	
 35	/** `owner/repo` split, as a repo is captured by a connection's feed. */
 36	export interface GithubRepoRef {
 37	  owner: string;
 38	  repo: string;
 39	}
 40	
 41	/** Injectable seams: tests drive the real graph build + gate with stubbed GitHub
 42	 * calls; the live tick wires the real repo list + collaborator API. */
 43	export interface GithubAclSyncDeps {
 44	  /** The repos this connection captures (from its feeds' config). */
 45	  listRepos: (params: { organizationId: string; connectionId: string }) => Promise<GithubRepoRef[]>;
 46	  /** A repo's current collaborators. Throws on a GitHub-level error (fail-closed). */
 47	  fetchCollaborators: (params: {
 48	    organizationId: string;
 49	    repo: GithubRepoRef;
 50	  }) => Promise<GithubRepoCollaborator[]>;
 51	}
 52	
 53	export interface GithubAclSyncResult {
 54	  ok: boolean;
 55	  reposSynced: number;
 56	}
 57	
 58	/**
 59	 * Sync ONE GitHub connection's repo-membership graph. Resolves its captured
 60	 * repos, fetches collaborators per repo, and builds the graph. See the file
 61	 * header for the fail-closed contract.
 62	 */
 63	export async function syncGithubConnectionAcl(
 64	  deps: GithubAclSyncDeps,
 65	  params: { connectionId: string; organizationId: string },
 66	): Promise<GithubAclSyncResult> {
 67	  const { connectionId, organizationId } = params;
 68	
 69	  const repos = await deps.listRepos({ organizationId, connectionId });
 70	  if (repos.length === 0) {
 71	    const reason = 'GitHub ACL sync unavailable: no repository feeds configured';
 72	    logger.error(
 73	      `${reason} — downgrading any existing ACL graph`,
 74	      { organization_id: organizationId, connection_id: connectionId },
 75	    );
 76	    await markConnectionAclFailed(organizationId, connectionId, reason);
 77	    return { ok: false, reposSynced: 0 };
 78	  }
 79	
 80	  try {
 81	    const repoInputs = [];
 82	    for (const repo of repos) {
 83	      const collaborators = await deps.fetchCollaborators({ organizationId, repo });
 84	      repoInputs.push({ fullName: `${repo.owner}/${repo.repo}`, collaborators });
 85	    }
 86	    await buildAccessGraph({
 87	      organizationId,
 88	      connectionId,
 89	      connectorKey: githubAclSource.key,
 90	      resourceNamespace: githubAclSource.resourceNamespace,
 91	      memberIdentities: githubAclSource.memberIdentities,
 92	      resources: githubReposToResources(repoInputs),
 93	    });
 94	    await clearConnectionAclError(organizationId, connectionId);
 95	    return { ok: true, reposSynced: repoInputs.length };
 96	  } catch (error) {
 97	    logger.error(
 98	      'GitHub ACL sync failed — marking connection fail-closed',
 99	      { organization_id: organizationId, connection_id: connectionId, error: String(error) },
100	    );
101	    await markConnectionAclFailed(
102	      organizationId,
103	      connectionId,
104	      `GitHub ACL sync failed: ${String(error)}`,
105	    );
106	    return { ok: false, reposSynced: 0 };
107	  }
108	}
109	
110	/** Parse `owner/repo` from a feed config (the GitHub connector stores
111	 * `repo_owner`/`repo_name`). Skips feeds without a fully-specified repo. */
112	function repoRefsFromFeedConfigs(configs: Array<Record<string, unknown> | null>): GithubRepoRef[] {
113	  const seen = new Set<string>();
114	  const refs: GithubRepoRef[] = [];
115	  for (const config of configs) {
116	    const owner = typeof config?.repo_owner === 'string' ? config.repo_owner.trim() : '';
117	    const repo = typeof config?.repo_name === 'string' ? config.repo_name.trim() : '';
118	    if (!owner || !repo) continue;
119	    const key = `${owner}/${repo}`.toLowerCase();
120	    if (seen.has(key)) continue;
121	    seen.add(key);
122	    refs.push({ owner, repo });
123	  }
124	  return refs;
125	}
126	
127	/** GitHub `/repos/{owner}/{repo}/collaborators`, paginated, bare `{login,id}`.
128	 * Throws on a non-OK response so the sync treats it fail-closed. */
129	async function fetchRepoCollaborators(
130	  token: string,
131	  repo: GithubRepoRef,
132	): Promise<GithubRepoCollaborator[]> {
133	  const collaborators: GithubRepoCollaborator[] = [];
134	  const perPage = 100;
135	  for (let page = 1; page <= 100; page++) {
120	   * the bot is NOT filtered out and can transiently gain a `member_of` edge —
121	   * self-healing on the next sync once the id backfills (a bot id maps to no
122	   * human requester, so this is audience inflation, never access leakage).
123	   */
124	  resolveBotIdentity: (params: {
125	    organizationId: string;
126	    teamId: string;
127	    /**
128	     * The connection being synced. Lets the resolver fall back to the
129	     * connection's own BYO bot credentials when the team has no OAuth
130	     * app-installation — otherwise a BYO Slack connection (active bot, real
131	     * bindings, no install row) never gets ACL-graphed and its channel memory
132	     * silently degrades to org scope.
133	     */
134	    connectionId: string;
135	  }) => Promise<{ token: string; botUserId: string | null } | null>;
136	}
137	
138	export interface SlackAclSyncResult {
139	  /** True when every bound Slack channel was fetched and graphed. */
140	  ok: boolean;
141	  teamsSynced: number;
142	  channelsSynced: number;
143	}
144	
145	/**
146	 * Sync ONE Slack connection's channel-membership graph. Resolves its captured
147	 * channels, fetches members per channel, and builds the graph (per team). See
148	 * the file header for the fail-closed contract.
149	 */
150	export async function syncSlackConnectionAcl(
151	  deps: SlackAclSyncDeps,
152	  params: { connectionId: string; organizationId: string },
153	): Promise<SlackAclSyncResult> {
154	  const { connectionId, organizationId } = params;
155	  const sql = getDb();
156	
157	  const bound = await resolveBoundChannelRows(sql, {
158	    organizationId,
159	    connectionId,
160	  });
161	
162	  // `resolveBoundChannelRows` narrows bindings to THIS connection (by slug), so
163	  // every row here already belongs to it — we trust connection_id as the scope,
164	  // NOT a team-string round-trip. `connTeamId` is only used to guard the BYO
165	  // multi-workspace case: when the connection's tenant id is itself a WORKSPACE
166	  // (`T…`), a binding for a DIFFERENT workspace is a stray second-connection row
167	  // and is dropped (fetched with the wrong token → fail-closed otherwise). When
168	  // the tenant id is NOT a workspace — a Grid ENTERPRISE (`E…`) org-wide install,
169	  // whose bindings correctly carry the sibling workspace `T…`, or a preview
170	  // connection (no teamId) — we accept EVERY real-team binding on the connection
171	  // and group by the binding's own team. Without this relaxation an org-wide
172	  // install (connTeamId = E…) drops all its `T…` bindings and silently
173	  // downgrades to the legacy per-agent fence.
174	  const [conn] = await sql<{ team_id: string | null }>`
175			SELECT COALESCE(external_tenant_id, config->'chatMetadata'->>'teamId') AS team_id
176			FROM connections
177			WHERE slug = ${runtimeConnectionIdToSlug(connectionId)}
178			  AND organization_id = ${organizationId}
179			  AND credential_mode IS NOT NULL
180			  AND deleted_at IS NULL
181			LIMIT 1
182		`;
183	  const connTeamId = conn?.team_id ?? null;
184	  // Is the connection's tenant id itself a concrete workspace? Only then do we
185	  // enforce workspace equality (BYO foreign-workspace guard). An enterprise `E…`
186	  // or absent tenant id does NOT constrain the binding team.
187	  const connScopesWorkspace = /^T[A-Z0-9]+$/i.test(connTeamId ?? '');
188	
189	  // Only Slack rows that carry a real workspace team can be team-scoped into the
190	  // graph; a channel with no team id is dropped fail-closed by the gate anyway.
191	  const slackRows = bound.filter(
192	    (r) =>
193	      r.platform.startsWith('slack') &&
194	      r.team_id &&
195	      (!connScopesWorkspace || r.team_id === connTeamId),
196	  );
197	  if (slackRows.length === 0) {
198	    return { ok: true, teamsSynced: 0, channelsSynced: 0 };
199	  }
200	
201	  // Group channels by workspace/team — one graph build per team.
202	  const byTeam = new Map<string, string[]>();
203	  for (const r of slackRows) {
204	    const channelId = stripPlatformPrefix(r.platform, r.channel_id);
205	    const list = byTeam.get(r.team_id as string) ?? [];
206	    list.push(channelId);
207	    byTeam.set(r.team_id as string, list);
208	  }
209	
210	  let teamsSynced = 0;
211	  let channelsSynced = 0;
212	  /*
213	   * One cutoff for the whole sync. The ACL state row is keyed by (org,
214	   * connection), not by team, so freshness is a single connection-level
215	   * decision: either no revocation landed after this sync began and the
216	   * connection may be blessed fresh, or one did and it may not. The cutoff is
217	   * taken before the FIRST workspace is read, so it covers every workspace's
218	   * snapshot — a per-team cutoff would let a late team bless membership the
219	   * revocation had already contradicted for an earlier one.
220	   */
221	  const [{ sync_started_at: syncStartedAt, acl_generation: aclGeneration }] = await sql<{
222	    sync_started_at: string;
223	    acl_generation: string | null;
224	  }>`
225			SELECT clock_timestamp()::text AS sync_started_at,
226			       (SELECT o.acl_generation::text FROM organization o WHERE o.id = ${organizationId})
227			         AS acl_generation
228		`;
229	  try {
230	    for (const [teamId, channelIds] of byTeam) {
231	      const identity = await deps.resolveBotIdentity({ organizationId, teamId, connectionId });
232	      if (!identity) {
233	        throw new Error(`No bot token for team ${teamId}`);
234	      }
235	      const { token, botUserId } = identity;
236	      const channels: SlackChannelInput[] = [];
237	      for (const channelId of channelIds) {
238	        // Per-channel tolerance for a STALE binding: if the bot was kicked, the
239	        // channel was archived/deleted, or it's simply not in it, Slack throws
240	        // `channel_not_found` / `not_in_channel` / `is_archived`. That channel
