  1	/**
  2	 * Helpers for writing the user's $member entity + entity_identities rows.
  3	 *
  4	 * Used by the signup hook to populate the identity graph so the gateway can
  5	 * later route inbound messages back to the right user's personal org via a
  6	 * single entity_identities lookup.
  7	 */
  8	
  9	import { normalizeSlackUserId, SLACK_IDENTITY } from "@lobu/connectors/slack-identity";
 10	import { fetchUserInfoWithRaw } from "../connect/oauth-providers";
 11	import { getDb } from "../db/client";
 12	import {
 13		type ResolvedTenantMember,
 14		resolveMemberOrgsForUser,
 15	} from "../identity/member-orgs";
 16	import logger from "../utils/logger";
 17	import {
 18		ensureMemberEntity,
