 37	interface EnsureMemberEntityParams {
 38	  organizationId: string;
 39	  /**
 40	   * The auth user whose IDENTITY this $member represents. Drives the
 41	   * `auth_user_id` claim (source `auth:signup`) the authz gate resolves on, and
 42	   * — for a self-provisioning caller — authorship. Pass this ONLY when the
